      "events": [],
      "narrative": "2006. augusztus 1-jétől a minisztérium és a tíz nemzeti park igazgatóság változatlan marad, de az új feladat- és hatásköri rendelet már egy helyen mondja ki, hogy a környezetvédelmi és vízügyi miniszter a Kormány természetvédelemért felelős tagja, előkészíti a természetvédelmi szabályokat, és irányítja a nemzeti park igazgatóságokat. Ez a snapshot a szervezeti folytonosság mellett a közfeladat jogi alapjának változását mutatja.",
