                "fertohansag_kincstar_est_date": "1990-12-01",
                "identity_join_note": "A rendelet név szerint rögzíti a közös jogelődöt és mindkét jogutódot. A 325752-es PIR folytonosságát a Fertő–Hanság K-TÖRZS-alapítási dátuma, a 763062-es új PIR-t és 2008. április 1-jei létrejöttét az Őrségi adatlap támasztja alá; a modell csak a külön PIR-rel megjelenő jogutód felé rajzol eseményélt, a 325752-es folytatást átnevezésként mutatja.",
