      "narrative": "2010. július 1-jétől a feladat- és hatásköri rendelet már kifejezetten a vidékfejlesztési minisztert nevezi meg természetvédelemért felelős kormánytagként és a nemzeti park igazgatóságok irányítójaként. A május 29-i általános jogi átadást ezzel felváltja a részletes, közvetlen feladatkijelölés.",
