      "events": [],
      "narrative": "2022. május 24-én lép hatályba a minisztériumok új felsorolása, az Agrárminisztérium változatlan néven és PIR-rel működik tovább. A 182/2022. Korm. rendeletet azonban csak ezen a napon hirdetik ki, ezért a természetvédelmi feladat és a nemzeti park igazgatóságok irányítása még egy napig a 94/2018-as szabályozás alapján marad ugyanennél a tárcánál.",
