      "events": [],
      "narrative": "2026. május 13-án lép hatályba a minisztériumi törvény: a 305679-es PIR-ű Agrárminisztérium Agrár- és Élelmiszergazdaságért Felelős Minisztérium néven működik tovább, és létrejön az új, 855437-es PIR-ű Élő Környezetért Felelős Minisztérium. A 90/2026. Korm. rendelet azonban csak másnap lép hatályba, ezért ezen a napon a természetvédelmi feladat és a nemzeti park igazgatóságok irányítása még a 2022-es feladatköri rendelet alapján a 305679-es tárca útvonalán marad.",
