      "events": [],
      "narrative": "2026. május 14-én, a 90/2026. Korm. rendelet hatálybalépésével a természetvédelmi felelősség és a nemzeti park igazgatóságok irányítása az új, 855437-es PIR-ű Élő Környezetért Felelős Minisztériumhoz kerül. A 305679-es PIR-ű Agrár- és Élelmiszergazdaságért Felelős Minisztérium nem szűnik meg, csak kikerül ebből a közfeladat-útvonalból. A K-TÖRZS 2026-08-30-i állapota mind a tíz igazgatóságnál még a 305679-es tárcát mutatja irányítóként, ezért az új jogi irányítási él nyilvántartási időeltérésként jelenik meg.",
